package com.adolfogonzalez.mareasihmpro.widget
import android.content.Context
object SurfaceCache { private const val FILE="mareas_surface_cache";fun save(context:Context,station:String,height:Double,next:String,uv:Double,wind:Double){context.getSharedPreferences(FILE,Context.MODE_PRIVATE).edit().putString("station",station).putFloat("height",height.toFloat()).putString("next",next).putFloat("uv",uv.toFloat()).putFloat("wind",wind.toFloat()).apply()};fun read(context:Context):Snapshot{val p=context.getSharedPreferences(FILE,Context.MODE_PRIVATE);return Snapshot(p.getString("station","Mareas IHM Pro")?:"Mareas IHM Pro",p.getFloat("height",0f).toDouble(),p.getString("next","Abre la app para actualizar")?:"Abre la app para actualizar",p.getFloat("uv",0f).toDouble(),p.getFloat("wind",0f).toDouble())}}
data class Snapshot(val station:String,val height:Double,val next:String,val uv:Double,val wind:Double)
